#include <vector>
#include <algorithm>

class Solution {
public:
    int maxFrequency(std::vector<int>& nums, int k) {
        int base = std::count(nums.begin(), nums.end(), k);
        int max_gain = 0;

        for (int target = 1; target <= 50; ++target) {
            if (target == k) continue;
            int curr = 0;
            int best = 0;
            for (int x : nums) {
                if (x == target) {
                    curr += 1;
                } else if (x == k) {
                    curr -= 1;
                }
                if (curr < 0) curr = 0;
                if (curr > best) best = curr;
            }
            if (best > max_gain) max_gain = best;
        }
        return base + max_gain;
    }
};

class Solution {
    public int maxFrequency(int[] nums, int k) {
        int base = 0;
        for (int x : nums) {
            if (x == k) base++;
        }
        int maxGain = 0;

        for (int target = 1; target <= 50; target++) {
            if (target == k) continue;
            int curr = 0;
            int best = 0;
            for (int x : nums) {
                if (x == target) {
                    curr++;
                } else if (x == k) {
                    curr--;
                }
                if (curr < 0) curr = 0;
                if (curr > best) best = curr;
            }
            if (best > maxGain) maxGain = best;
        }
        return base + maxGain;
    }
}

var maxFrequency = function(nums, k) {
    let base = 0;
    for (let i = 0; i < nums.length; i++) {
        if (nums[i] === k) base++;
    }
    let maxGain = 0;

    for (let target = 1; target <= 50; target++) {
        if (target === k) continue;
        let curr = 0;
        let best = 0;
        for (let i = 0; i < nums.length; i++) {
            const x = nums[i];
            if (x === target) {
                curr++;
            } else if (x === k) {
                curr--;
            }
            if (curr < 0) curr = 0;
            if (curr > best) best = curr;
        }
        if (best > maxGain) maxGain = best;
    }
    return base + maxGain;
};
